const raw = $input.first().json || {};
const spaces = Array.isArray(raw.spaces) ? raw.spaces : [];
const dms = spaces.filter((s) => String(s.spaceType || '') === 'DIRECT_MESSAGE' || !s.spaceType);

if (!spaces.length) {
  return [{
    json: {
      ok: false,
      hint: 'No spaces returned. DM the expensen8nworkflow Chat app once, then re-run. Do not use the new-project app unless its SA is this credential.',
      spaceIds: [],
    },
  }];
}

return [{
  json: {
    ok: true,
    count: spaces.length,
    spaceIds: spaces.map((s) => s.name).filter(Boolean),
    dmSpaceIds: dms.map((s) => s.name).filter(Boolean),
    spaces,
  },
}];
